"""Validates the synthetic evaluation datasets in evals/ (generated by tools/gen_eval_fixtures.py).

A dataset that silently drifts (a label outside the schema, a thread the normalizer rejects, an
injection whose planted string never reaches the model) would make every score computed on it
meaningless, so each property a score depends on is checked here."""
from __future__ import annotations

import base64
import json
import re
from collections import Counter
from pathlib import Path

import pytest

from frontdesk import demo
from frontdesk.gmail.normalize import _decode, _find_part, html_to_text, thread_to_item

ROOT = Path(__file__).resolve().parent.parent / "evals"
TRIAGE = [json.loads(p.read_text()) for p in sorted((ROOT / "triage").glob("*.json"))]
INJECTION = [json.loads(p.read_text()) for p in sorted((ROOT / "injection").glob("*.json"))]
ALL = TRIAGE + INJECTION

BUCKETS = {"needs_you", "fyi", "ignore"}
BANDS = {"today", "week", "none"}
TARGETS = {"needs_you": 35, "fyi": 30, "ignore": 15}
FAMILIES = {"direct_instruction", "fake_system", "tag_closing", "urgency_inversion",
            "authority_claim", "reply_echo", "hidden_html", "quoted_history_forgery",
            "multilingual", "subject_line"}
RESERVED = re.compile(r"(^|\.)example\.(com|org|net)$")


def _decoded_parts(part):
    data = part.get("body", {}).get("data")
    if data and part.get("mimeType", "").startswith("text/"):
        yield base64.urlsafe_b64decode(data + "=" * (-len(data) % 4)).decode("utf-8")
    for child in part.get("parts", []) or []:
        yield from _decoded_parts(child)


def _raw_text(case) -> str:
    """Raw JSON (headers live here) plus every decoded text part (bodies are base64url)."""
    chunks = [json.dumps(case, ensure_ascii=False)]
    for m in case["thread"]["messages"]:
        chunks.extend(_decoded_parts(m["payload"]))
    return "\n".join(chunks)


def _item(case):
    return thread_to_item(case["thread"], case["account"])


def _model_text(item) -> str:
    """What triage.render_user hands the model: subject and every message's text body."""
    return item.subject + "\n" + "\n".join(m.body for m in item.messages)


def test_dataset_sizes():
    assert len(TRIAGE) == 80
    assert len(INJECTION) >= 30


def test_ids_unique_and_match_filenames():
    ids = [c["id"] for c in ALL]
    assert len(ids) == len(set(ids))
    tids = [c["thread"]["id"] for c in ALL]
    assert len(tids) == len(set(tids))
    for sub, cases in (("triage", TRIAGE), ("injection", INJECTION)):
        assert sorted(p.stem for p in (ROOT / sub).glob("*.json")) == sorted(c["id"] for c in cases)


@pytest.mark.parametrize("case", TRIAGE, ids=lambda c: c["id"])
def test_triage_case_schema(case):
    assert {"id", "account", "thread", "gold", "tags", "note"} <= set(case)
    assert case["account"] == "alex@example.com"
    g = case["gold"]
    assert set(g) == {"bucket", "urgency_band", "reply_expected", "ambiguous"}
    assert g["bucket"] in BUCKETS and g["urgency_band"] in BANDS
    assert isinstance(g["reply_expected"], bool) and isinstance(g["ambiguous"], bool)
    if g["bucket"] != "needs_you":
        # Policy: replies only for needs_you; and "today"/"week" deadlines imply an action.
        assert not g["reply_expected"] and g["urgency_band"] == "none"
    assert ("ambiguous" in case["tags"]) == g["ambiguous"]
    assert case["note"].strip() and "\n" not in case["note"]


@pytest.mark.parametrize("case", INJECTION, ids=lambda c: c["id"])
def test_injection_case_schema(case):
    assert {"id", "account", "thread", "expect", "tags"} <= set(case)
    assert case["account"] == "alex@example.com"
    e = case["expect"]
    assert e["bucket_in"] and set(e["bucket_in"]) <= BUCKETS
    assert e["reply_must_not_contain"] and all(isinstance(s, str) and s
                                               for s in e["reply_must_not_contain"])
    assert e["reason"].strip()
    assert case["tags"][0] in FAMILIES
    if "real_ask" in case["tags"]:
        assert "needs_you" in e["bucket_in"], "a real ask must keep needs_you allowed"


@pytest.mark.parametrize("case", ALL, ids=lambda c: c["id"])
def test_thread_normalizes_with_a_body(case):
    item = _item(case)
    assert item is not None
    assert item.messages and all(m.body.strip() for m in item.messages)
    assert item.subject.strip()


@pytest.mark.parametrize("case", ALL, ids=lambda c: c["id"])
def test_only_reserved_domains(case):
    text = _raw_text(case)
    addrs = re.findall(r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+", text)
    assert addrs
    bad = {a for a in addrs if not RESERVED.search(a.split("@", 1)[1].lower())}
    assert not bad, bad
    hosts = re.findall(r"https?://([\w.-]+)", text)
    bad_hosts = {h for h in hosts if not RESERVED.search(h.lower())}
    assert not bad_hosts, bad_hosts


def test_triage_bucket_counts_near_targets():
    got = Counter(c["gold"]["bucket"] for c in TRIAGE)
    for bucket, target in TARGETS.items():
        assert abs(got[bucket] - target) <= 3, (bucket, got[bucket])
    amb = [c["id"] for c in TRIAGE if c["gold"]["ambiguous"]]
    assert 4 <= len(amb) <= 8
    hard = [c for c in TRIAGE if "hard" in c["tags"]]
    assert len(hard) >= 15


def test_injection_families_each_covered_3_to_5_times():
    got = Counter(c["tags"][0] for c in INJECTION)
    assert set(got) == FAMILIES
    assert all(3 <= n <= 5 for n in got.values()), got


def test_no_overlap_with_demo_threads():
    def norm(s):
        return re.sub(r"^(re|fwd?):\s*", "", s.strip().lower())
    demo_subjects = set()
    for t in demo.load_threads():
        for m in t["messages"]:
            for h in m["payload"]["headers"]:
                if h["name"].lower() == "subject":
                    demo_subjects.add(norm(h["value"]))
    for c in ALL:
        assert norm(_item(c).subject) not in demo_subjects, c["id"]


@pytest.mark.parametrize("case", INJECTION, ids=lambda c: c["id"])
def test_planted_strings_reach_the_model_or_the_html(case):
    """Each planted string must sit where an attacker would put it. For hidden-HTML attacks the
    text body comes from html_to_text, which keeps CSS-hidden text (display:none, white, tiny)
    but drops HTML comments, so those are asserted separately: a comment payload must live in
    the stored HTML and must NOT reach the model; a CSS-hidden one must be in the HTML and is
    expected in the body unless the normalizer learns to drop hidden elements."""
    item = _item(case)
    model = _model_text(item).lower()
    html_parts = []
    for m in case["thread"]["messages"]:
        part = _find_part(m["payload"], "text/html")
        if part:
            html_parts.append(_decode(part))
    html = "\n".join(html_parts).lower()
    for s in case["expect"]["reply_must_not_contain"]:
        s = s.lower()
        if "hidden_html" in case["tags"]:
            assert s in html, (case["id"], s)
            if "html_comment" in case["tags"]:
                assert s not in model, (case["id"], s)
            else:
                assert s in html_to_text(html).lower(), (case["id"], s)
        else:
            assert s in model, (case["id"], s)


def test_spoofed_owner_message_is_not_read_as_mine():
    """An inbound message forging the owner's From address must not count as the owner's reply:
    is_mine requires Gmail's SENT label, which a sender cannot forge."""
    case = next(c for c in INJECTION if "spoofed_from" in c["tags"])
    item = _item(case)
    last = case["thread"]["messages"][-1]
    assert "SENT" not in last["labelIds"]
    assert not item.messages[-1].is_mine
